"use client";

import { Field } from "@base-ui/react/field";
import type { ComponentProps, ReactNode } from "react";

import { Input } from "@/components/ui/input";
import type { IconComponent } from "@/lib/icon-context";
import { useShape } from "@/lib/shape-context";
import { SizeProvider, useSizeVariant, useSize } from "@/lib/size-context";
import type { SizeVariant } from "@/lib/size-context";
import { cn } from "@/lib/utils";

export const InputGroup = ({
  size,
  className,
  ...props
}: ComponentProps<"div"> & { size?: SizeVariant }) => {
  const density = useSizeVariant(size);
  return (
    <SizeProvider size={density}>
      <div
        className={cn("flex w-72 max-w-full flex-col gap-3", className)}
        {...props}
      />
    </SizeProvider>
  );
};

export interface InputFieldProps extends Omit<
  ComponentProps<typeof Input>,
  "prefix"
> {
  label: ReactNode;
  description?: ReactNode;
  error?: ReactNode;
  prefix?: ReactNode;
  suffix?: ReactNode;
  addon?: ReactNode;
  icon?: IconComponent;
  labelHidden?: boolean;
}

export const InputField = ({
  label,
  description,
  error,
  prefix,
  suffix,
  addon,
  icon: FieldIcon,
  labelHidden,
  className,
  disabled,
  density,
  shape,
  ...props
}: InputFieldProps) => {
  const sizes = useSize(density);
  const radius = useShape(shape);
  return (
    <Field.Root
      disabled={disabled}
      invalid={!!error}
      className={cn("flex flex-col gap-1", sizes.text, className)}
    >
      <Field.Label
        className={cn(sizes.px, "text-muted-foreground", labelHidden && "sr-only")}
      >
        {label}
      </Field.Label>
      <div
        className={cn(
          "flex items-center overflow-hidden border border-input transition-[border-color,box-shadow] duration-(--motion-fast) focus-within:border-ring focus-within:ring-2 focus-within:ring-ring/30 has-[[aria-invalid=true]]:border-destructive has-[:disabled]:opacity-50",
          radius
        )}
      >
        {(prefix || FieldIcon) && (
          <span
            className={cn(
              "flex shrink-0 items-center text-muted-foreground",
              sizes.px,
              "pe-0",
              sizes.gap,
              sizes.iconClass
            )}
          >
            {FieldIcon && <FieldIcon aria-hidden="true" />}
            {prefix}
          </span>
        )}
        <Input
          density={density}
          shape={shape}
          className={cn(
            "rounded-none border-0 shadow-none focus-visible:ring-0",
            (prefix || FieldIcon) &&
              (sizes.variant === "compact" ? "ps-1" : "ps-2"),
            suffix && (sizes.variant === "compact" ? "pe-1" : "pe-2")
          )}
          {...props}
        />
        {suffix && (
          <span className={cn("shrink-0 text-muted-foreground", sizes.px, "ps-0")}>
            {suffix}
          </span>
        )}
        {addon && (
          <span
            className={cn(
              "flex shrink-0 items-center self-stretch border-l border-input bg-muted",
              sizes.px
            )}
          >
            {addon}
          </span>
        )}
      </div>
      {description && (
        <Field.Description className={cn(sizes.px, "text-xs text-muted-foreground")}>
          {description}
        </Field.Description>
      )}
      {error && (
        <Field.Error match className={cn(sizes.px, "text-xs text-destructive")}>
          {error}
        </Field.Error>
      )}
    </Field.Root>
  );
};

"use client";
import { Input as Primitive } from "@base-ui/react/input";

import { useShape } from "@/lib/shape-context";
import type { ShapeVariant } from "@/lib/shape-context";
import { useSize } from "@/lib/size-context";
import type { SizeVariant } from "@/lib/size-context";
import { cn } from "@/lib/utils";

const Input = ({
  className,
  type,
  density,
  shape,
  ...props
}: Omit<React.ComponentProps<typeof Primitive>, "className"> & {
  className?: string;
  density?: SizeVariant;
  shape?: ShapeVariant;
}) => {
  const sizes = useSize(density);
  const radius = useShape(shape);
  return (
    <Primitive
      type={type}
      data-slot="input"
      className={cn(
        "file:text-foreground placeholder:text-muted-foreground selection:bg-primary selection:text-primary-foreground dark:bg-input/30 border-input flex h-9 w-full min-w-0 rounded-md border bg-transparent px-3 py-1 text-base shadow-xs transition-[color,box-shadow] outline-none file:inline-flex file:h-7 file:border-0 file:bg-transparent file:text-sm file:font-medium disabled:pointer-events-none disabled:cursor-not-allowed disabled:opacity-50 md:text-sm",
        "focus-visible:border-ring focus-visible:ring-ring/50 focus-visible:ring-[3px]",
        "aria-invalid:ring-destructive/20 dark:aria-invalid:ring-destructive/40 aria-invalid:border-destructive",
        sizes.control,
        sizes.px,
        radius,
        sizes.variant === "compact" && "md:text-xs",
        className
      )}
      {...props}
    />
  );
};

export { Input };

"use client";

import {
  Check,
  ChevronDown,
  ChevronRight,
  Copy,
  LoaderCircle,
  Search,
  X,
} from "lucide-react";
import { createContext, useContext, useMemo } from "react";
import type { ComponentType, ReactNode, SVGProps } from "react";

export type IconProps = SVGProps<SVGSVGElement> & {
  size?: number;
  strokeWidth?: number;
};
export type IconComponent = ComponentType<IconProps>;
export const defaultIcons = {
  check: Check,
  "chevron-down": ChevronDown,
  "chevron-right": ChevronRight,
  close: X,
  copy: Copy,
  loading: LoaderCircle,
  search: Search,
} satisfies Record<string, IconComponent>;
export type IconName = keyof typeof defaultIcons;
const IconContext =
  createContext<Record<IconName, IconComponent>>(defaultIcons);
export const IconProvider = ({
  icons,
  children,
}: {
  icons: Partial<Record<IconName, IconComponent>>;
  children: ReactNode;
}) => {
  const parent = useContext(IconContext);
  const value = useMemo(() => ({ ...parent, ...icons }), [parent, icons]);
  return <IconContext.Provider value={value}>{children}</IconContext.Provider>;
};
export const Icon = ({ name, ...props }: IconProps & { name: IconName }) => {
  const Component = useContext(IconContext)[name];
  return <Component aria-hidden="true" focusable="false" {...props} />;
};

"use client";

import { createContext, useContext } from "react";
import type { ReactNode } from "react";

export type ShapeVariant = "rounded" | "pill";
const ShapeContext = createContext<ShapeVariant>("rounded");
export const shapeMap = {
  pill: "rounded-[20px]",
  rounded: "rounded-lg",
} as const;
export const ShapeProvider = ({
  shape,
  children,
}: {
  shape: ShapeVariant;
  children: ReactNode;
}) => <ShapeContext.Provider value={shape}>{children}</ShapeContext.Provider>;
export const useShape = (override?: ShapeVariant) => {
  const inherited = useContext(ShapeContext);
  return shapeMap[override ?? inherited];
};

"use client";

import { createContext, useContext } from "react";
import type { ReactNode } from "react";

export type SizeVariant = "default" | "compact";
const SizeContext = createContext<SizeVariant>("default");
export const sizeMap = {
  compact: {
    control: "h-7",
    controlHeight: 28,
    gap: "gap-1",
    icon: 14,
    iconClass: "[&_svg:not([class*='size-'])]:size-3.5",
    px: "px-2.5",
    text: "text-xs",
    variant: "compact",
  },
  default: {
    control: "h-9",
    controlHeight: 36,
    gap: "gap-2",
    icon: 16,
    iconClass: "[&_svg:not([class*='size-'])]:size-4",
    px: "px-3",
    text: "text-[13px]",
    variant: "default",
  },
} as const;
export const SizeProvider = ({
  size,
  children,
}: {
  size: SizeVariant;
  children: ReactNode;
}) => <SizeContext.Provider value={size}>{children}</SizeContext.Provider>;
export const useSizeVariant = (override?: SizeVariant) => {
  const inherited = useContext(SizeContext);
  return override ?? inherited;
};
export const useSize = (override?: SizeVariant) =>
  sizeMap[useSizeVariant(override)];
